 fs.writeFileSync(path.join(target,'index.html'),'<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>可靠图片真实 React 合成验证</title><link rel="stylesheet" href="/preview.css"><style>body{margin:0;background:#f6f5f2;color:#222;font:16px/1.5 system-ui,sans-serif}main{padding:12px;max-width:1100px;margin:auto;box-sizing:border-box}button,input,select{min-height:44px;font:inherit}label{display:inline-flex;align-items:center;gap:6px;margin:6px}.fixture-tools{display:flex;flex-wrap:wrap;gap:6px}.fixture-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,280px),1fr));gap:14px}.fixture-card{min-width:0}.fixture-card img{display:block;width:100%;height:auto;aspect-ratio:3/2;object-fit:contain}.fixture-card button,.fixture-card a{max-width:100%;box-sizing:border-box}.fixture-parent{display:block;width:100%;padding:0}.fixture-state{padding:10px;background:#eceae4;overflow-wrap:anywhere}.ri-fallback{aspect-ratio:3/2}.photo-lightbox{position:fixed;inset:0;z-index:100;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:20px;background:rgba(0,0,0,.9);color:white}.photo-lightbox figure{max-width:95vw;max-height:85vh;margin:10px}.photo-lightbox img{max-width:95vw;max-height:75vh;object-fit:contain}.photo-lightbox button{margin:4px}.photo-lightbox-close{align-self:flex-end}</style><div id="root"></div><script src="/preview.js"></script></html>');console.log(target);
